-- ---------------------------------------------------------------
-- Table privileges: SELECT on all tables (minus secret columns), write privileges only where a write policy exists.
-- Columns matching (ciphertext|password_hash) are never client-readable (clients must name columns explicitly on those tables).
-- ---------------------------------------------------------------
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated;
DO $$
DECLARE r record; cols text;
BEGIN
    FOR r IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
        SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position) INTO cols
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = r.tablename AND column_name !~ '(ciphertext|password_hash)';
        EXECUTE format('GRANT SELECT (%s) ON public.%I TO authenticated', cols, r.tablename);
    END LOOP;
END $$;
GRANT INSERT, UPDATE, DELETE ON academic_term, academic_year, activity_evidence_requirement, activity_type, admission_application, admission_category, announcement, announcement_attachment, announcement_type, approval_status, assessment_component, assessment_event, attendance_correction_request, attendance_status, award_category, awarding_body, awarding_body_type, blood_group, building, campus, caste, certificate_request, certificate_type, class_batch, class_section, class_session, cocurricular_activity, cocurricular_category, conference_activity, conference_activity_indexing, conference_contribution_type, conference_event, confidentiality_level, consultancy_project, counselling_session, country, course_catalog, course_category, course_offering, course_offering_section, course_offering_section_student, course_prerequisite, curriculum_course, curriculum_scheme, department, designation, document_type, education_institution, education_institution_type, employee, employee_aadhaar, employee_address, employee_assignment, employee_bank_account, employee_competency, employee_document, employee_document_access_rule, employee_document_category, employee_pan, employee_previous_employment, employee_qualification, employee_sensitive_access_audit, employment_source, enrolment_status_history, event_mode, evidence_document, evidence_document_audit, evidence_document_tag, evidence_document_version, evidence_tag, evidence_type, external_agency, external_organization, external_organization_type, extracurricular_activity, extracurricular_category, faculty_course_assignment, faculty_internship, feedback_choice, feedback_cycle, feedback_question, feedback_question_category, feedback_questionnaire, feedback_questionnaire_item, feedback_response, feedback_response_item, funded_research_project, funding_agency, funding_type, gender, grade_rule, grade_scale, grievance, grievance_action, grievance_category, indexing_agency, industry_sector, journal, journal_metric, journal_publication, journal_publication_indexing, journal_type, membership_type, mentor_assignment, metric_type, organization_type, organizer, participation_level, previous_organization, previous_organization_type, professional_contribution_type, professional_development_activity, programme, programme_specialization, programme_term_offering, publication_type, publisher, qualification_level, religion, research_project_financial_utilization, research_proposal, research_status, research_supervision, role_type, room, semester, social_category, staff_activity, staff_activity_contributor, staff_award, staff_category, staff_professional_contribution, staff_professional_membership, staff_type, state, student, student_activity, student_activity_evidence, student_activity_evidence_audit, student_activity_evidence_requirement, student_activity_evidence_version, student_activity_team_member, student_activity_type, student_address, student_assessment_mark, student_attendance, student_course_registration, student_course_result, student_document, student_entrance_exam, student_exit, student_parent_guardian, student_previous_education, student_programme_enrolment, student_residence, student_term_registration, student_term_result, study_mode, sub_caste, time_slot, timetable_session, training_program_type, university, verification_status TO authenticated;
DO $$
DECLARE r record;
BEGIN
    FOR r IN SELECT viewname FROM pg_views WHERE schemaname = 'public' LOOP
        EXECUTE format('GRANT SELECT ON public.%I TO authenticated', r.viewname);
    END LOOP;
END $$;
